    function openDataEditor(event) {
        const moduleName = event.target.closest('.sna-module-item').dataset.moduleName;
        const module = getActiveSchemeModules().find(m => m.name === moduleName);
        if (!module) return;
        mainDocument_SNA.getElementById('sna-data-editor-window').dataset.moduleName = moduleName;
        mainDocument_SNA.getElementById('sna-data-editor-title').textContent = `编辑数据 - ${moduleName}`;
        mainDocument_SNA.getElementById('sna-data-editor-textarea').value = JSON.stringify(module.data, null, 2);
        mainDocument_SNA.getElementById('sna-data-editor-backdrop').style.display = 'block';
        mainDocument_SNA.getElementById('sna-data-editor-window').style.display = 'flex';
