    function closeConfigEditor() {
        mainDocument_SNA.getElementById('sna-config-editor-backdrop').style.display = 'none';
        mainDocument_SNA.getElementById('sna-config-editor-window').style.display = 'none';
    }

    function handleSchemeChange(event) { switchScheme(event.target.value); }

    function handleNewScheme() {
        let newName = prompt("请输入新方案的名称：");
        if (!newName) { toastr_API_SNA.info("创建已取消。"); return; }
        while (assistantData.schemes[newName]) {
            newName = prompt(`方案名称 "${newName}" 已存在。请输入一个新名称：`);
            if (!newName) { toastr_API_SNA.info("创建已取消。"); return; }
        }
        assistantData.schemes[newName] = { modules: [] };
        switchScheme(newName);
    }

    function handleDeleteScheme() {
        const localSchemesCount = Object.keys(assistantData.schemes).filter(name => name !== TEMP_SCHEME_NAME).length;
        if (localSchemesCount <= 1) { toastr_API_SNA.warning("不能删除最后一个本地方案。"); return; }
        const schemeToDelete = assistantData.activeScheme;
        if (confirm(`你确定要删除方案 "${schemeToDelete}" 吗？此操作无法撤销。`)) {
            delete assistantData.schemes[schemeToDelete];
            const nextScheme = Object.keys(assistantData.schemes).find(s => s !== TEMP_SCHEME_NAME) || null;
            switchScheme(nextScheme);
            toastr_API_SNA.success(`方案 "${schemeToDelete}" 已被删除。`);
        }
    }


    function handleRenameScheme() {
        const oldName = assistantData.activeScheme;
        let newName = prompt(`请输入方案 "${oldName}" 的新名称：`, oldName);
        if (!newName || newName === oldName) { toastr_API_SNA.info("重命名已取消。"); return; }
        if (assistantData.schemes[newName]) { toastr_API_SNA.error(`方案名称 "${newName}" 已存在。`); return; }
        assistantData.schemes[newName] = assistantData.schemes[oldName];
        delete assistantData.schemes[oldName];
        switchScheme(newName);
    }

    function handleExportScheme() {
        const schemeToExport = { modules: getActiveSchemeModules() };
        const dataStr = JSON.stringify(schemeToExport, null, 2);
        const blob = new Blob([dataStr], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const a = mainDocument_SNA.createElement('a');
        a.href = url;
        a.download = `${assistantData.activeScheme.replace(/[\\/:"*?<>|]/g, '_')}.sna_scheme.json`;
        a.click();
        URL.revokeObjectURL(url);
        toastr_API_SNA.info(`方案 "${assistantData.activeScheme}" 已开始导出。`);
    }

    function handleImportScheme(event) {
        const file = event.target.files[0];
        if (!file) return;
        const reader = new FileReader();
        reader.onload = (e) => {
            try {
                const importedScheme = JSON.parse(e.target.result);
                if (!Array.isArray(importedScheme.modules)) throw new Error("导入的方案文件格式不正确，缺少 'modules' 数组。");
                let newName = prompt("请输入新方案的名称：", file.name.replace(/\.sna_scheme\.json$/, ''));
                if (!newName) { toastr_API_SNA.info("导入已取消。"); return; }
                while (assistantData.schemes[newName]) {
                    newName = prompt(`方案名称 "${newName}" 已存在。请输入一个新名称：`);
                    if (!newName) { toastr_API_SNA.info("导入已取消。"); return; }
                }
                assistantData.schemes[newName] = importedScheme;
                switchScheme(newName);
                toastr_API_SNA.success(`方案 "${newName}" 已成功导入并激活。`);
            } catch (error) {
                toastr_API_SNA.error(`方案导入失败：${error.message}`);
            } finally {
                event.target.value = '';
                event.target.onchange = null;
            }
        };
        reader.readAsText(file);
    }

    function handleSaveData() {
        const moduleName = mainDocument_SNA.getElementById('sna-data-editor-window').dataset.moduleName;
        const textarea = mainDocument_SNA.getElementById('sna-data-editor-textarea');
        try {
            const newData = JSON.parse(textarea.value);
            if (!Array.isArray(newData)) throw new Error("数据必须是一个数组。");
            getActiveSchemeModules().find(m => m.name === moduleName).data = newData;
            updateModuleCache(moduleName);
            saveAssistantData();
            updateCombinedMacro(); // 刷新宏系统以确保依赖此模块的其他模块能获取最新输出
            toastr_API_SNA.success(`模块 "${moduleName}" 的数据已保存！`);
            closeDataEditor();
        } catch (error) {
            toastr_API_SNA.error(`保存失败：${error.message}`);
        }
    }

    function handleSaveConfig() {
        const moduleName = mainDocument_SNA.getElementById('sna-config-editor-window').dataset.moduleName;
        try {
            const module = getActiveSchemeModules().find(m => m.name === moduleName);
            const newLogic = mainDocument_SNA.getElementById('sna-config-logic-editor').value;
            const nodeIdRegex = mainDocument_SNA.getElementById('sna-config-regex-input').value;
            const newMacro = mainDocument_SNA.getElementById('sna-config-macro-input').value;

            if (!newMacro) { toastr_API_SNA.error('触发宏不能为空。'); return; }
            new RegExp(nodeIdRegex); // Test validity
            new Function('currentNodeId', 'storyNodes', 'storyData', newLogic); // Test validity

            module.customLogic = newLogic;
            module.searchTarget = mainDocument_SNA.getElementById('sna-config-search-target').value;
            module.nodeIdRegex = nodeIdRegex;
            module.macro = newMacro;
            module.processMacrosBeforeSearch = mainDocument_SNA.getElementById('sna-config-process-macros-checkbox').checked;
            module.enableChaining = mainDocument_SNA.getElementById('sna-config-chaining-checkbox').checked;
            if (module.searchTarget === 'macro') {
                const designatedMacro = mainDocument_SNA.getElementById('sna-source-macro-input').value;
                if (!designatedMacro.trim()) { toastr_API_SNA.error('来源宏不能为空。'); return; }
                module.designatedMacro = designatedMacro;
            }

            saveAssistantData();
            updateCombinedMacro();
            toastr_API_SNA.success(`模块 "${moduleName}" 的配置已保存！`);
            closeConfigEditor();
        } catch (error) {
             toastr_API_SNA.error(`配置保存失败：${error.message}。请检查正则或代码语法。`);
        }
    }

    function handleToggleEnable(event) {
        const moduleName = event.target.closest('.sna-module-item').dataset.moduleName;
        const isEnabled = event.target.checked;
        getActiveSchemeModules().find(m => m.name === moduleName).enabled = isEnabled;
        saveAssistantData();
        updateCombinedMacro();
        toastr_API_SNA.info(`模块 "${moduleName}" 已${isEnabled ? '启用' : '禁用'}。`);
    }

    function handleReorderModule(event, direction) {
        const moduleName = event.target.closest('.sna-module-item').dataset.moduleName;
        const modules = getActiveSchemeModules();
        const index = modules.findIndex(m => m.name === moduleName);
        if (direction === 'up' && index > 0) {
            [modules[index - 1], modules[index]] = [modules[index], modules[index - 1]];
        } else if (direction === 'down' && index < modules.length - 1) {
            [modules[index], modules[index + 1]] = [modules[index + 1], modules[index]];
        } else { return; }
        saveAssistantData();
        populateModuleManager();
        updateCombinedMacro();
    }

    function handleNewModule() {
        let newName = prompt("请输入新模块的名称：");
        if (!newName) { toastr_API_SNA.info("创建已取消。"); return; }
        const activeModules = getActiveSchemeModules();
        while (activeModules.some(m => m.name === newName)) {
            newName = prompt(`名称 "${newName}" 已存在。请输入一个新名称：`);
            if (!newName) { toastr_API_SNA.info("创建已取消。"); return; }
        }
        activeModules.push({ name: newName, ...DEFAULT_MODULE_CONFIG });
        updateModuleCache(newName);
        saveAssistantData();
        updateCombinedMacro();
        populateModuleManager();
        toastr_API_SNA.success(`模块 "${newName}" 已创建。`);
    }

    function handleImportModule(event) {
        const file = event.target.files[0];
        if (!file) return;
        const reader = new FileReader();
        reader.onload = (e) => {
            try {
                const importedContent = JSON.parse(e.target.result);
                let newModuleData;
                const suggestedName = file.name.replace(/\.(sna_module|sna_data)\.json$/, '');

                if (Array.isArray(importedContent)) {
                    toastr_API_SNA.info("检测到数据文件，将使用默认配置创建新模块。");
                    newModuleData = { ...DEFAULT_MODULE_CONFIG, data: importedContent };
                } else if (typeof importedContent === 'object' && importedContent !== null && 'data' in importedContent && 'customLogic' in importedContent) {
                    toastr_API_SNA.info("检测到完整模块文件，将导入配置与数据。");
                    newModuleData = { ...DEFAULT_MODULE_CONFIG, ...importedContent };
                } else {
                    throw new Error("无法识别的文件格式。请确保文件是模块数据数组或完整的模块配置对象。");
                }

                let newName = prompt("请输入新模块的名称：", suggestedName);
                if (!newName) { toastr_API_SNA.info("导入已取消。"); return; }

                const activeModules = getActiveSchemeModules();
                while (activeModules.some(m => m.name === newName)) {
                    newName = prompt(`名称 "${newName}" 已存在。请输入一个新名称：`);
                    if (!newName) { toastr_API_SNA.info("导入已取消。"); return; }
                }

                newModuleData.name = newName;
                activeModules.push(newModuleData);
                updateModuleCache(newName);
                saveAssistantData();
                updateCombinedMacro();
                populateModuleManager();
                toastr_API_SNA.success(`模块 "${newName}" 已成功导入到当前方案。`);
            } catch (error) {
                toastr_API_SNA.error(`模块导入失败：${error.message}`);
            } finally {
                event.target.value = '';
                event.target.onchange = null;
            }
        };
        reader.readAsText(file);
    }

    function handleExportModule(event) {
        const moduleName = event.target.closest('.sna-module-item').dataset.moduleName;
        const module = getActiveSchemeModules().find(m => m.name === moduleName);
        if (!module) return;

        const includeConfig = confirm("是否连同模块的配置一同导出？\n\n选择“确定”将导出包含完整配置的模块文件 (.sna_module.json)。\n选择“取消”将只导出模块的数据部分 (.sna_data.json)。");

        let dataToExport, fileName;

        if (includeConfig) {
            const { name, ...configAndData } = module;
            dataToExport = configAndData;
            fileName = `${module.name.replace(/[\\/:"*?<>|]/g, '_')}.sna_module.json`;
        } else {
            dataToExport = module.data;
            fileName = `${module.name.replace(/[\\/:"*?<>|]/g, '_')}.sna_data.json`;
        }

        const dataStr = JSON.stringify(dataToExport, null, 2);
        const blob = new Blob([dataStr], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const a = mainDocument_SNA.createElement('a');
        a.href = url;
        a.download = fileName;
        a.click();
        URL.revokeObjectURL(url);
        toastr_API_SNA.info(`模块 "${moduleName}" 已开始导出。`);
    }

    function handleDeleteModule(event) {
        const moduleName = event.target.closest('.sna-module-item').dataset.moduleName;
        if (confirm(`你确定要删除模块 "${moduleName}" 吗？此操作无法撤销。`)) {
            const modules = getActiveSchemeModules();
            const index = modules.findIndex(m => m.name === moduleName);
            if (index > -1) {
                modules.splice(index, 1);
                moduleCaches.delete(moduleName);
                saveAssistantData();
                updateCombinedMacro();
                populateModuleManager();
                toastr_API_SNA.success(`模块 "${moduleName}" 已被删除。`);
            }
        }
    }

    function handleRestoreConfig() {
        if(confirm("你确定要将脚本逻辑恢复到默认设置吗？未保存的更改将会丢失。")) {
            mainDocument_SNA.getElementById('sna-config-logic-editor').value = DEFAULT_NODE_OUTPUT_LOGIC;
            toastr_API_SNA.info("逻辑已恢复到默认值。点击“保存配置”以应用。");
        }
    }

    function handleTestRun() {
        const moduleName = mainDocument_SNA.getElementById('sna-config-editor-window').dataset.moduleName;
        const testNodeId = mainDocument_SNA.getElementById('sna-config-test-node-id').value;
        const logicToTest = mainDocument_SNA.getElementById('sna-config-logic-editor').value;
        const outputElement = mainDocument_SNA.getElementById('sna-config-test-output');
        const tempStoryData = getActiveSchemeModules().find(m => m.name === moduleName).data;
        const tempStoryNodes = createRegexMapProxy(tempStoryData);
        if (!testNodeId) { outputElement.textContent = '【测试错误】请输入一个要测试的节点ID。'; return; }
        if (!tempStoryNodes.has(testNodeId)) { outputElement.textContent = `【测试错误】节点ID "${testNodeId}" 在当前模块数据中找不到匹配项。`; return; }
        try {
            const dynamicFunction = new Function('currentNodeId', 'storyNodes', 'storyData', logicToTest);
            const result = dynamicFunction(testNodeId, tempStoryNodes, tempStoryData);
            outputElement.textContent = result;
        } catch (e) {
            outputElement.textContent = `【测试错误】执行脚本逻辑时出错: ${e.message}`;
        }
    }

    function handleClearCache() {
        if (confirm("你确定要刷新缓存吗？此操作将使用当前内存中的数据，清除并重写浏览器中存储的所有方案。")) {
            try {
                localStorage.removeItem(STORAGE_KEY);
                localStorage.removeItem(OLD_STORAGE_KEY_V3_5);
                localStorage.removeItem(OLD_STORAGE_KEY_V3_2);
                saveAssistantData();
                populateSchemeSelector();
                populateModuleManager();
                updateCombinedMacro(); // 刷新宏系统
                toastr_API_SNA.success("缓存已刷新，并使用当前会话中的数据重新写入。");
            } catch (error) {
                toastr_API_SNA.error("刷新缓存时发生错误: " + error.message);
            }
        }
    }

    function addStoryNodeMenuItem() {
        const extensionsMenu = jQuery_API_SNA('#extensionsMenu', mainDocument_SNA);
        if (!extensionsMenu.length) { setTimeout(addStoryNodeMenuItem, 1000); return; }
        const menuItemHTML = `
            <div class="extension_container interactable" id="${SCRIPT_ID_PREFIX_SNA}-menu-item-container" tabindex="0">
                <div class="list-group-item flex-container flexGap5 interactable" id="${SCRIPT_ID_PREFIX_SNA}-menu-item" title="打开剧情节点助手">
                    <div class="fa-fw fa-solid fa-code-branch extensionsMenuExtensionButton"></div>
                    <span>剧情节点助手</span>
                </div>
            </div>`;
        const $menuItemContainer = jQuery_API_SNA(menuItemHTML);
        $menuItemContainer.find(`#${SCRIPT_ID_PREFIX_SNA}-menu-item`).on('click', function (e) {
            e.stopPropagation();
            const exMenuBtn = jQuery_API_SNA('#extensionsMenuButton', mainDocument_SNA);
            if (exMenuBtn.length && extensionsMenu.is(':visible')) exMenuBtn.trigger('click');
            setTimeout(() => openManagerWindow(), 150);
        });
        extensionsMenu.append($menuItemContainer);
    }

    function attemptToLoadCoreApis_SNA() {
        const parentWin = (typeof window.parent !== 'undefined' ? window.parent : window);
        SillyTavern_API_SNA = parentWin.SillyTavern;
        TavernHelper_API_SNA = parentWin.TavernHelper;
        jQuery_API_SNA = parentWin.jQuery || parentWin.$;
        toastr_API_SNA = parentWin.toastr;
        coreApisAreReady_SNA = !!(SillyTavern_API_SNA && TavernHelper_API_SNA && jQuery_API_SNA && toastr_API_SNA);
        return coreApisAreReady_SNA;
    }

async function mainInitialize_SNA() {
    initAttempts_SNA++;
    if (attemptToLoadCoreApis_SNA()) {
        console.log('【调试】剧情节点助手: 核心API已加载，mainInitialize_SNA 开始执行。'); // <--- 添加日志 1

        const parentWin = (typeof window.parent !== 'undefined' ? window.parent : window);
        mainDocument_SNA = parentWin.document;
        if (!mainDocument_SNA) {
            console.error('剧情节点助手: 无法确定主文档，脚本无法继续运行。');
            return;
        }
        cleanup_SNA();
        loadData();
        createUI();

        await loadSchemeFromLorebook_SNA();

        addStoryNodeMenuItem();
        updateCombinedMacro();

        if (eventOn && tavern_events) {
            console.log('【调试】剧情节点助手: eventOn 和 tavern_events 存在，准备注册监听器...'); // <--- 添加日志 2
            const reloadLorebookScheme = () => {
                console.log("【调试】剧情节点助手: 事件触发！重新检查世界书方案。"); // <--- 添加日志 3
                loadSchemeFromLorebook_SNA();
            };
            eventOn(tavern_events.CHAT_CHANGED, reloadLorebookScheme);
            console.log('【调试】剧情节点助手: 监听器已尝试注册。'); // <--- 添加日志 4
        } else {
            console.error('【调试】剧情节点助手: eventOn 或 tavern_events 未找到，无法注册监听器！'); // <--- 添加日志 5
        }

        toastr_API_SNA.success('剧情节点助手 v4.2.0 已成功加载！');
        console.log('剧情节点助手 v4.2.0 已初始化。');
        } else if (initAttempts_SNA < maxInitAttempts_SNA) {
            console.log(`剧情节点助手: 核心API未就绪，正在重试... (尝试 ${initAttempts_SNA}/${maxInitAttempts_SNA})`);
            setTimeout(mainInitialize_SNA, initInterval_SNA);
        } else {
            console.error('剧情节点助手: 多次尝试后初始化失败，脚本无法运行。');
        }
    }

    if (window[SCRIPT_LOADED_FLAG_SNA]) {
        console.warn('剧情节点助手: 检测到旧的加载标志，可能正在重新加载。');
    }
    window[SCRIPT_LOADED_FLAG_SNA] = true;

    console.log('剧情节点助手: 正在启动...');
    if (document.readyState === 'complete' || document.readyState === 'interactive') {
        setTimeout(mainInitialize_SNA, 1000);
    } else {
        document.addEventListener('DOMContentLoaded', () => {
            setTimeout(mainInitialize_SNA, 1000);
        });
    }
})();

