        const settingsHTML = `<div id="${SETTINGS_PANEL_ID}"><div class="tmm-header"><h3>模板编辑</h3><button class="tmm-close-btn">×</button></div><div class="tmm-content tmm-settings-grid"><div class="tmm-setting-card"><h4>表格结构模板 (JSON)</h4><p style="font-size: 0.9em; color: #aaa;">定义所有表格的名称和列。修改后，你可能需要开始新对话或手动删除旧的表格数据才能看到变化。</p><textarea id="tmm-template-editor"></textarea></div></div><div class="tmm-footer"><button id="tmm-template-reset" class="tmm-btn">恢复默认模板</button><button id="tmm-template-save" class="tmm-btn save">保存模板</button></div><div class="tmm-resizer"></div></div>`;
