    <div id="galgame-container" class="galgame-container">
        <!-- Lenses and selector will be dynamically inserted here -->
    </div>

    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const container = document.getElementById('galgame-container');
            const rawData = `$1`;
            if (!container || !rawData) return;

            const lenses = [];
            const lensRegex = /<(主镜头|分镜)\s*([^>]*)>([\s\S]*?)<\/\1>/g;
            let match;

            // 1. 从原始数据中解析所有镜头
            while ((match = lensRegex.exec(rawData)) !== null) {
                const type = match[1];
                const name = (type === '主镜头') ? '主镜头' : match[2].trim();
                const content = match[3].trim();
                // 使用名称和索引创建唯一的ID，防止重名导致问题
                const id = `lens-${name.replace(/\s+/g, '-')}-${lenses.length}`;
                const icon = (type === '主镜头') ? '🎥' : '🎬';

                lenses.push({ type, name, content, id, icon });
            }

            // 如果没有解析到任何镜头，则不进行渲染
            if (lenses.length === 0) return;

            const mainLens = lenses.find(lens => lens.type === '主镜头');
            const subLenses = lenses.filter(lens => lens.type !== '主镜头');

            // 为了保持顺序，我们将主镜头（如果存在）放到数组最前面
            const orderedLenses = mainLens ? [mainLens, ...subLenses] : subLenses;

            const lensSelector = document.createElement('div');
            lensSelector.className = 'lens-selector';

            // 2. 动态创建HTML元素
            orderedLenses.forEach((lens, index) => {
                const isActive = index === 0;

                // 创建内容块
                const contentBlock = document.createElement('div');
                contentBlock.id = lens.id;
                contentBlock.className = `perspective-block lens-content ${isActive ? 'revealed' : 'hidden'}`;

                let contentHTML = lens.content;
                // 为引号包裹的文本添加样式
                const quoteRegex = /(「.*?」|『.*?』|“.*?”|‘.*?’|".*?"|'.*?')/g;
                contentHTML = contentHTML.replace(quoteRegex, '<span class="quoted-text">$&</span>');

                contentBlock.innerHTML = `
                    <div class="perspective-header">
                        <span class="icon">${lens.icon}</span> ${lens.name}
                    </div>
                    <div class="perspective-content">${contentHTML}</div>
                `;
                container.appendChild(contentBlock);

                // 创建切换标签
                const tab = document.createElement('span');
                tab.className = `lens-tab ${isActive ? 'active' : ''}`;
                tab.dataset.target = lens.id;
                tab.textContent = lens.name;
                lensSelector.appendChild(tab);
            });

            container.appendChild(lensSelector);

            // 3. 绑定切换事件
            lensSelector.addEventListener('click', (event) => {
                const clickedTab = event.target.closest('.lens-tab');
                if (!clickedTab) return;

                const targetId = clickedTab.dataset.target;

                container.querySelectorAll('.lens-tab').forEach(tab => tab.classList.remove('active'));
                clickedTab.classList.add('active');

                container.querySelectorAll('.lens-content').forEach(content => {
                    if (content.id === targetId) {
                        content.classList.remove('hidden');
                        content.classList.add('revealed');
                    } else {
                        content.classList.add('hidden');
                        content.classList.remove('revealed');
                    }
                });
            });
        });
    </script>
</body>
</html>
