let output = \`{[本轮回复所在节点: \${currentNode.节点ID}]\\n\${currentNode.时间} \${currentNode.节点描述}\\n}\`;

if (currentNode.后置节点 && currentNode.后置节点.length > 0) {
    output += '\\n*后续分支*\\n';
    currentNode.后置节点.forEach((nextNodeId, index) => {
        const nextNode = storyNodes.get(nextNodeId);
        if (nextNode) {
            const optionLetter = String.fromCharCode(65 + index);
            output += \`{选项 \${optionLetter} -> [通向节点: \${nextNode.节点ID}] \${nextNode.时间} \${nextNode.描述}}\\n\`;
        }
    });
} else if (currentNode.通向结局) {
    output += \`\\n{[结局达成: \${currentNode.通向结局}}\`;
} else {
    output += '\\n{无后续分支}';
}
output += '\\n{额外添加两个留在当前ID节点，扩展丰富当前节点剧情的选项}';

return output.trim();`;

    const DEFAULT_MODULE_CONFIG = {
        enabled: true,
        data: JSON.parse(JSON.stringify(defaultStoryData)),
        searchTarget: 'user',
        designatedMacro: '',
        processMacrosBeforeSearch: false,
        enableChaining: false,
        nodeIdRegex: '(?:\\[当前节点\\s*[:：]\\s*([a-zA-Z0-9_]+)\\s*\\])|(N\\d+)',
        customLogic: DEFAULT_NODE_OUTPUT_LOGIC,
        macro: '\{\{666故事节点666\}\}'
    };

    // --- 核心逻辑 ---
    function escapeRegex(string) {
        if(!string) return '';
        return string.replace(/[-\/\\^$*+?.()|[\]{}]/g, '\\$&');
    }

    /**
     * 创建一个特殊的Map代理，使其get和has方法能够处理正则表达式作为键。
     * @param {Array} nodesArray - 包含故事节点的数组。
     * @returns {Map} - 一个行为类似Map的代理对象。
     */
    function createRegexMapProxy(nodesArray) {
        const compiledNodes = nodesArray.map(node => {
            let regex = null;
            try {
                // 将节点ID编译成一个完全匹配的正则表达式
                regex = new RegExp(`^${node.节点ID}$`);
            } catch (e) {
                console.warn(`剧情节点助手: 在节点ID中发现无效的正则表达式: "${node.节点ID}"`, e);
            }
            return { nodeData: node, regex: regex };
        });

        const findNodeByKey = (key) => {
            if (key === null || typeof key === 'undefined') return undefined;
            for (const compiledNode of compiledNodes) {
                try {
                    if (compiledNode.regex && compiledNode.regex.test(key)) {
                        return compiledNode.nodeData;
                    }
                } catch (e) { /* 忽略测试时可能出现的错误 */ }

                // 为无效的正则或精确匹配提供回退
                if (compiledNode.nodeData.节点ID === key) {
                    return compiledNode.nodeData;
                }
            }
            return undefined;
        };

        // 创建一个真实的Map实例，以便代理那些我们不自定义处理的方法（如.size, .clear等）
        const realMap = new Map(nodesArray.map(node => [node.节点ID, node]));

        return new Proxy(realMap, {
            get: (target, prop, receiver) => {
                if (prop === 'get') {
                    return findNodeByKey;
                }
                if (prop === 'has') {
                    return (key) => findNodeByKey(key) !== undefined;
                }

                // 对于其他所有属性和方法，使用原始Map的行为
                const value = Reflect.get(target, prop, receiver);
                return typeof value === 'function' ? value.bind(target) : value;
            },
        });
    }

    function getActiveSchemeModules() {
        const activeSchemeName = assistantData.activeScheme;
        if (activeSchemeName && assistantData.schemes && assistantData.schemes[activeSchemeName]) {
            return assistantData.schemes[activeSchemeName].modules || [];
        }
        return [];
    }

    function updateCombinedMacro() {
        if (!coreApisAreReady_SNA || !TavernHelper_API_SNA) return;

        if (lastCombinedCallback_SNA) {
            try {
                const eventClearListenerFn = TavernHelper_API_SNA.eventClearListener;
                if (typeof eventClearListenerFn === 'function') {
                    eventClearListenerFn(lastCombinedCallback_SNA);
                }
            } catch (e) { console.error("剧情节点助手: 卸载旧宏回调时出错:", e); }
            lastCombinedCallback_SNA = null;
        }

        const activeModules = getActiveSchemeModules();
        const allMacroStrings = activeModules
            .filter(m => m.enabled && m.macro)
            .map(m => `(${escapeRegex(m.macro)})`);

        if (allMacroStrings.length === 0) {
            combinedMacroRegex_SNA = null;
            return;
        }

        try {
            combinedMacroRegex_SNA = new RegExp(allMacroStrings.join('|'), 'g');
            const registerFn = TavernHelper_API_SNA.registerMacros || TavernHelper_API_SNA.registerMacroLike;
            if (typeof registerFn !== 'function') throw new Error("TavernHelper中未找到宏注册函数 (registerMacros / registerMacroLike)。");

            const combinedCallback = (context, matchedString) => {
                 const orderedActiveModules = getActiveSchemeModules();
                 for (const module of orderedActiveModules) {
                    if (module.enabled && module.macro === matchedString) {
                        return executeNodeLogicForModule(module.name);
                    }
                }
                return matchedString; // Fallback
            };

            lastCombinedCallback_SNA = TavernHelper_API_SNA.errorCatched(combinedCallback);
            registerFn(combinedMacroRegex_SNA, lastCombinedCallback_SNA);
        } catch (e) {
            console.error("剧情节点助手: 创建或注册组合宏时出错:", e);
            toastr_API_SNA.error(`创建组合宏时出错: ${e.message}`);
            combinedMacroRegex_SNA = null;
            lastCombinedCallback_SNA = null;
        }
    }

    function updateModuleCache(moduleName) {
        const module = getActiveSchemeModules().find(m => m.name === moduleName);
        if (!module || !Array.isArray(module.data)) {
            console.error(`剧情节点助手: 模块 "${moduleName}" 的故事数据格式错误。`);
            moduleCaches.delete(moduleName);
            return;
        }
        const storyNodesProxy = createRegexMapProxy(module.data);
        moduleCaches.set(moduleName, { storyNodes: storyNodesProxy });
    }

    function updateAllCachesForActiveScheme() {
        moduleCaches.clear();
        const activeModules = getActiveSchemeModules();
        for (const module of activeModules) {
            updateModuleCache(module.name);
        }
    }

    function saveAssistantData() {
        // Do not save the temporary scheme
        const dataToSave = JSON.parse(JSON.stringify(assistantData));
        if (dataToSave.schemes && dataToSave.schemes[TEMP_SCHEME_NAME]) {
            delete dataToSave.schemes[TEMP_SCHEME_NAME];
        }
        localStorage.setItem(STORAGE_KEY, JSON.stringify(dataToSave));
    }


    function loadData() {
        let savedDataStr = localStorage.getItem(STORAGE_KEY);
        let dataToParse = savedDataStr;

        // Migration from old versions
        if (!dataToParse) {
            const oldData_v35 = localStorage.getItem(OLD_STORAGE_KEY_V3_5);
            if (oldData_v35) {
                console.log("剧情节点助手: 检测到 v3.5 数据，准备迁移到 v4.0...");
                dataToParse = oldData_v35;
                localStorage.removeItem(OLD_STORAGE_KEY_V3_5);
            } else {
                const oldData_v32 = localStorage.getItem(OLD_STORAGE_KEY_V3_2);
                if (oldData_v32) {
                    console.log("剧情节点助手: 检测到 v3.2 数据，准备迁移...");
                    try {
                        const oldData = JSON.parse(oldData_v32);
                        const migratedData = {
                            activeScheme: '默认方案',
                            schemes: { '默认方案': { modules: oldData.modules || oldData.dataSets || {} } }
                        };
                        dataToParse = JSON.stringify(migratedData);
                        localStorage.removeItem(OLD_STORAGE_KEY_V3_2);
                    } catch (e) { console.error("迁移v3.2数据失败", e); }
                }
            }
        }

        if (dataToParse) {
            try {
                assistantData = JSON.parse(dataToParse);
            } catch (error) {
                console.error("剧情节点助手: 解析本地数据失败:", error);
                assistantData = {};
            }
        } else {
            assistantData = {};
        }

        // Data integrity and migration to ordered array
        let migrated = false;
        if (!assistantData.schemes || Object.keys(assistantData.schemes).length === 0) {
            assistantData = {
                activeScheme: '默认方案',
                schemes: { '默认方案': { modules: [{ name: '默认故事', ...DEFAULT_MODULE_CONFIG }] } }
            };
            migrated = true;
        } else {
            for (const schemeName in assistantData.schemes) {
                const scheme = assistantData.schemes[schemeName];
                if (scheme.modules && !Array.isArray(scheme.modules)) {
                    console.log(`剧情节点助手: 正在为方案 "${schemeName}" 迁移模块结构...`);
                    const orderedModules = [];
                    const moduleNames = Object.keys(scheme.modules).sort();
                    for (const moduleName of moduleNames) {
                        orderedModules.push({ name: moduleName, ...scheme.modules[moduleName] });
                    }
                    scheme.modules = orderedModules;
                    migrated = true;
                }
            }
        }

        if (!assistantData.activeScheme || !assistantData.schemes[assistantData.activeScheme]) {
            assistantData.activeScheme = Object.keys(assistantData.schemes)[0];
        }

        if (assistantData.activeScheme === TEMP_SCHEME_NAME) {
             assistantData.activeScheme = Object.keys(assistantData.schemes).find(s => s !== TEMP_SCHEME_NAME) || null;
        }

        if (migrated) {
            toastr_API_SNA.info("数据结构已更新以支持新功能。");
            saveAssistantData();
        }

        updateAllCachesForActiveScheme();
        updateCombinedMacro();
    }

    async function loadSchemeFromLorebook_SNA() {
        if (!coreApisAreReady_SNA) return;

        const wasTempSchemeActive = assistantData.activeScheme === TEMP_SCHEME_NAME;
        if (assistantData.schemes[TEMP_SCHEME_NAME]) {
            delete assistantData.schemes[TEMP_SCHEME_NAME];
        }

        let newSchemeLoaded = false;
        try {
            const lorebookName = await TavernHelper_API_SNA.getCurrentCharPrimaryLorebook();
            if (lorebookName) {
                const entries = await TavernHelper_API_SNA.getLorebookEntries(lorebookName);
                const schemeEntry = entries.find(entry => entry.comment === LOREBOOK_ENTRY_NAME);

                if (schemeEntry && schemeEntry.content) {
                    try {
                        const parsedScheme = JSON.parse(schemeEntry.content);
                        if (parsedScheme && Array.isArray(parsedScheme.modules)) {
                            assistantData.schemes[TEMP_SCHEME_NAME] = parsedScheme;
                            toastr_API_SNA.success(`已从角色卡加载方案: "${TEMP_SCHEME_NAME}"`);
                            switchScheme(TEMP_SCHEME_NAME);
                            newSchemeLoaded = true;
                        }
                    } catch (e) {
                        console.error(`剧情节点助手: 解析世界书条目 "${LOREBOOK_ENTRY_NAME}" 的内容时出错:`, e);
                    }
                }
            }
        } catch (e) {
            console.error('剧情节点助手: 检查世界书方案时出错:', e);
        }

        if (!newSchemeLoaded && wasTempSchemeActive) {
            const fallbackScheme = Object.keys(assistantData.schemes).find(s => s !== TEMP_SCHEME_NAME) || null;
            if(fallbackScheme){
                 toastr_API_SNA.info(`角色卡方案已移除，切换回: "${fallbackScheme}"`);
                 switchScheme(fallbackScheme);
            } else {
                 populateSchemeSelector(); // Refresh UI if no schemes left
            }
        } else {
            populateSchemeSelector(); // Always refresh selector to add/remove temp option
        }
    }

    function switchScheme(schemeName) {
        if (!assistantData.schemes[schemeName]) {
            toastr_API_SNA.error(`无法切换到方案 "${schemeName}"，因为它不存在。`);
            return;
        }
        assistantData.activeScheme = schemeName;

        if (schemeName !== TEMP_SCHEME_NAME) {
            saveAssistantData();
        }

        const isTempSchemeActive = assistantData.activeScheme === TEMP_SCHEME_NAME;
        const managerWindow = mainDocument_SNA.getElementById('sna-manager-window');
        if(managerWindow && managerWindow.style.display !== 'none') {
            mainDocument_SNA.getElementById('sna-rename-scheme-btn').disabled = isTempSchemeActive;
            mainDocument_SNA.getElementById('sna-delete-scheme-btn').disabled = isTempSchemeActive;
        }

        populateSchemeSelector();
        populateModuleManager();
        updateAllCachesForActiveScheme();
        updateCombinedMacro();
        toastr_API_SNA.success(`已切换到方案: "${schemeName}"`);
    }

    function executeNodeLogicForModule(moduleName) {
        if (macroExecutionStack_SNA.includes(moduleName)) {
            const cycle = [...macroExecutionStack_SNA, moduleName].join(' -> ');
            console.error(`剧情节点助手: 检测到循环依赖: ${cycle}`);
            return `【错误】检测到循环依赖: ${cycle}`;
        }
        macroExecutionStack_SNA.push(moduleName);

        const parentWin = (typeof window.parent !== 'undefined' ? window.parent : window);

        try {
            if (!coreApisAreReady_SNA) return "【错误】核心API未就绪。";

            const module = getActiveSchemeModules().find(m => m.name === moduleName);
            const cache = moduleCaches.get(moduleName);

            if (!module) return `【错误】模块 "${moduleName}" 未加载。`;
            if (!cache || !cache.storyNodes) return `【错误】模块 "${moduleName}" 的缓存未初始化。`;

            const { storyNodes } = cache;
            const { data: storyData, searchTarget, designatedMacro, nodeIdRegex: nodeIdRegexStr, customLogic, processMacrosBeforeSearch, enableChaining } = module;

            let currentNodeId = null;
            let searchContent = '';

            try {
                if (searchTarget === 'macro') {
                    if (designatedMacro) {
                        const activeModules = getActiveSchemeModules();
                        const targetModule = activeModules.find(m => m.enabled && m.macro && m.macro === designatedMacro);

                        if (targetModule) {
                            // 是我们自己的宏。递归执行其逻辑。
                            searchContent = executeNodeLogicForModule(targetModule.name);
                        } else {
                            // 不是我们自己的宏，依次检查是否为表格记忆大师的宏，然后是通用Tavern宏
                            let handled = false;

                            console.log(`【调试】剧情节点助手(${moduleName}): 检查来源宏 "${designatedMacro}"`);

                            // 修正后的逻辑：
                            if (parentWin.TableMemoryMasterAPI) {
                                console.log(`【调试】剧情节点助手(${moduleName}): 成功找到 parentWin.TableMemoryMasterAPI 对象。`);

                                if (designatedMacro === '{{666表格记忆666}}') {
                                    if (typeof parentWin.TableMemoryMasterAPI.getTableAsMarkdown === 'function') {
                                        console.log(`【调试】剧情节点助手(${moduleName}): 匹配到宏 "{{666表格记忆666}}"，调用 getTableAsMarkdown...`);
                                        searchContent = parentWin.TableMemoryMasterAPI.getTableAsMarkdown();
                                        handled = true;
                                        console.log(`【调试】剧情节点助手(${moduleName}): getTableAsMarkdown 返回内容:`, searchContent);
                                    } else {
                                        console.error(`【调试】剧情节点助手(${moduleName}): 错误 - 找到了API对象，但 getTableAsMarkdown 不是一个函数。`);
                                    }
                                } else {
                                    const variableMacroMatch = designatedMacro.match(/\{\{表格记忆变量_(\d+)_(\d+)_(\d+)\}\}/);
                                    if (variableMacroMatch) {
                                         if (typeof parentWin.TableMemoryMasterAPI.getCellValueByMacro === 'function') {
                                            console.log(`【调试】剧情节点助手(${moduleName}): 匹配到宏 "${designatedMacro}"，调用 getCellValueByMacro...`);
                                            const [, tableIndex, rowIndex, colIndex] = variableMacroMatch;
                                            searchContent = parentWin.TableMemoryMasterAPI.getCellValueByMacro(null, designatedMacro, tableIndex, rowIndex, colIndex);
                                            handled = true;
                                            console.log(`【调试】剧情节点助手(${moduleName}): getCellValueByMacro 返回内容:`, searchContent);
                                        } else {
                                            console.error(`【调试】剧情节点助手(${moduleName}): 错误 - 找到了API对象，但 getCellValueByMacro 不是一个函数。`);
                                        }
                                    }
                                }
                            } else {
                                console.error(`【调试】剧情节点助手(${moduleName}): 错误 - 未找到 parentWin.TableMemoryMasterAPI 对象！请确保“表格记忆大师”脚本已正确加载并运行。`);
                            }

                            // 如果不是表格记忆大师的宏，则作为通用Tavern宏处理
                            if (!handled) {
                                console.log(`【调试】剧情节点助手(${moduleName}): 宏 "${designatedMacro}" 未被表格记忆大师处理，将作为通用宏由 TavernHelper 处理。`);
                                searchContent = TavernHelper_API_SNA.substitudeMacros(designatedMacro);
                            }
                        }
                    } else {
                        return `【错误】模块 "${moduleName}" 配置为从宏检索，但未指定来源宏。`;
                    }
                } else {
                    const messagesOfRole = TavernHelper_API_SNA.getChatMessages('0-{{lastMessageId}}', { role: searchTarget || 'user' });
                    const lastMessage = messagesOfRole && messagesOfRole.length > 0 ? messagesOfRole.pop() : null;
                    if (lastMessage) {
                        searchContent = lastMessage.message;
                    }
                    if (searchContent && processMacrosBeforeSearch) {
                        searchContent = TavernHelper_API_SNA.substitudeMacros(searchContent);
                    }
                }

                if (searchContent) {
                    const regex = new RegExp(nodeIdRegexStr || '(N\\d+)', 'g');
                    let match;
                    const foundIds = [];
                    while ((match = regex.exec(searchContent)) !== null) {
                        const potentialId = match[1] || match[2] || match[0];
                        if (storyNodes.has(potentialId)) {
                            foundIds.push(potentialId);
                        }
                    }
                    if (foundIds.length > 0) {
                        currentNodeId = foundIds[foundIds.length - 1];
                    }
                }
            } catch (e) {
                console.error(`剧情节点助手(${moduleName}): 查找节点ID时出错:`, e);
                return `【错误】模块 "${moduleName}" 查找节点ID时出错: ${e.message}。请检查正则或来源宏设置。`;
            }

            const dynamicFunction = new Function('currentNodeId', 'storyNodes', 'storyData', customLogic);
            let result = dynamicFunction(currentNodeId, storyNodes, storyData);

            if (enableChaining) {
                result = TavernHelper_API_SNA.substitudeMacros(result);
            }

            return result;

        } catch (e) {
            console.error(`剧情节点助手(${moduleName}): 执行自定义逻辑时出错:`, e);
            return `【错误】模块 "${moduleName}" 执行脚本逻辑时出错: ${e.message}。请在配置中检查并修正。`;
        } finally {
            macroExecutionStack_SNA.pop();
        }
    }


