                loadSchemeFromLorebook_SNA();
            };
            eventOn(tavern_events.CHAT_CHANGED, reloadLorebookScheme);
            console.log('【调试】剧情节点助手: 监听器已尝试注册。'); // <--- 添加日志 4
        } else {
            console.error('【调试】剧情节点助手: eventOn 或 tavern_events 未找到，无法注册监听器！'); // <--- 添加日志 5
        }

        toastr_API_SNA.success('剧情节点助手 v4.2.0 已成功加载！');
        console.log('剧情节点助手 v4.2.0 已初始化。');
        } else if (initAttempts_SNA < maxInitAttempts_SNA) {
            console.log(`剧情节点助手: 核心API未就绪，正在重试... (尝试 ${initAttempts_SNA}/${maxInitAttempts_SNA})`);
            setTimeout(mainInitialize_SNA, initInterval_SNA);
        } else {
            console.error('剧情节点助手: 多次尝试后初始化失败，脚本无法运行。');
