})();

// ==UserScript==
// @name         表格记忆大师
// @version      3.3.0
// @description  通过可编辑的悬浮面板和强大的表格模板系统，实现AI驱动的自动化数据管理和记忆增强。采用 Sheet/Cell 数据结构，实现更精细的数据追溯。新增从角色卡世界书加载专用模板的功能，并支持单元格变量宏和Excel导入导出。
// @author       飞云
// @match        */*
// @grant        none
// ==/UserScript==

(function () {
    'use strict';

    // --- 脚本配置 ---
    const SCRIPT_ID_PREFIX = 'tableMemoryMaster';
    const SETTINGS_PANEL_ID = `${SCRIPT_ID_PREFIX}-settings-panel`;
    const DATA_PANEL_ID = `${SCRIPT_ID_PREFIX}-data-panel`;
    const VIEWER_BUTTON_ID = `${SCRIPT_ID_PREFIX}-viewer-button`;

    const STORAGE_KEY_SETTINGS = `${SCRIPT_ID_PREFIX}-settings_v1`;
    const STORAGE_KEY_DATA_PANEL_STATE = `${SCRIPT_ID_PREFIX}-data-panel-state_v1`;
    const STORAGE_KEY_SETTINGS_PANEL_STATE = `${SCRIPT_ID_PREFIX}-settings-panel-state_v1`;
    const STORAGE_KEY_BUTTON_POS = `${SCRIPT_ID_PREFIX}-button-position_v1`;
    const CHAT_DATA_KEY = `TMM_ChatData_v3`; // 数据结构版本升级
    const LOREBOOK_TEMPLATE_ENTRY_NAME = '表格记忆大师专用表格结构'; // 从世界书读取模板的条目名称

    const AI_DATA_BLOCK_REGEX = /<tableEdit>([\s\S]*?)<\/tableEdit>/i;

    const DEFAULT_TABLE_TEMPLATE = `{
"tableStructure":[
{"tableIndex":0,"tableName":"当前信息表","columns":["日期编码","地点编码","此地角色"]},
{"tableIndex":1,"tableName":"角色信息表","columns":["角色名","性别+年龄+性格","职业","爱好","身份","隐藏身份","心印","其他","对<user>关系","对<user>的态度"]},
{"tableIndex":2,"tableName":"地点编码表","columns":["编码","地点"]},
{"tableIndex":3,"tableName":"日期编码表","columns":["编码","日期"]},
{"tableIndex":4,"tableName":"任务约定表","columns":["角色","任务","完成情况"]},
{"tableIndex":5,"tableName":"事件历史表","columns":["事件","日期编码","地点编码","重要变化"]},
{"tableIndex":6,"tableName":"能力记录表","columns":["拥有人","能力名","效果","代价","来源"]},
{"tableIndex":7,"tableName":"重要物品表","columns":["拥有人","物品名","描述","效果/意义","来源"]},
{"tableIndex":8,"tableName":"大总结表","columns":["序号","内容"]},
{"tableIndex":9,"tableName":"数值变量表（特定且有限）","columns":["相关角色（禁止更改此第0列）","变量1列","变量2列","变量3列","变量4列","变量5列","变量6列","变量7列","变量8列","变量9列","变量10列"]}
]
}`;

    // --- 状态变量 ---
    let SillyTavern_API, TavernHelper_API, jQuery_API, toastr_API;
    let isApiReady = false;
    let $settingsPanel, $dataPanel;
    let currentSettings = {};
    let currentTableData = null; 
    let isUpdating = false;

    // --- 日志与通知 ---
    function logDebug(...args) { console.log(`%c[表格记忆大师 DEBUG]`, 'color: #3498db; font-weight: bold;', ...args); }
    function logError(...args) { console.error(`%c[表格记忆大师 ERROR]`, 'color: #e74c3c; font-weight: bold;', ...args); }
    function logWarn(...args) { console.warn(`%c[表格记忆大师 WARN]`, 'color: #f39c12; font-weight: bold;', ...args); }
    function showToast(type, message) { toastr_API?.[type]?.(message, '表格记忆大师'); }

    function escapeHtml(str) {
        if (str === null || str === undefined) return '';
        if (typeof str !== 'string') str = String(str);
        const a = document.createElement('a');
        a.appendChild(document.createTextNode(str));
        return a.innerHTML;
    }

    function generateUid(prefix = 'uid_') {
        return `${prefix}${Date.now().toString(36)}_${Math.random().toString(36).substr(2, 9)}`;
    }

    // --- 核心数据处理 (v3.0.0 重构) ---

    function loadSettings() {
        const defaults = {
            enabled: true,
            autoUpdate: true,
            tableTemplate: DEFAULT_TABLE_TEMPLATE
        };
        try {
            const saved = localStorage.getItem(STORAGE_KEY_SETTINGS);
            currentSettings = saved ? { ...defaults, ...JSON.parse(saved) } : defaults;
        } catch (e) {
            logError("加载设置失败", e);
            currentSettings = defaults;
        }
    }

    function saveSettings() {
        try {
            localStorage.setItem(STORAGE_KEY_SETTINGS, JSON.stringify(currentSettings));
        } catch (e) {
            logError("保存设置失败", e);
            showToast('error', '保存设置失败，浏览器存储可能已满。');
        }
    }

    // 新增：从角色卡主世界书加载专用模板
    async function loadTemplateFromLorebook() {
        logDebug('[loadTemplateFromLorebook] 检查角色卡专用表格模板...');
        if (!isApiReady) {
            logWarn('[loadTemplateFromLorebook] API未就绪，跳过检查。');
            return false;
        }

        try {
            const lorebookName = await TavernHelper_API.getCurrentCharPrimaryLorebook();
            if (!lorebookName) {
                logDebug('[loadTemplateFromLorebook] 未找到主世界书，使用全局/默认模板。');
                return false;
            }

            const entries = await TavernHelper_API.getLorebookEntries(lorebookName);
            const templateEntry = entries.find(entry => entry.comment === LOREBOOK_TEMPLATE_ENTRY_NAME);

            if (templateEntry && templateEntry.content) {
                logDebug(`[loadTemplateFromLorebook] 在世界书 "${lorebookName}" 中找到专用模板条目。`);
                try {
                    const parsedTemplate = JSON.parse(templateEntry.content);
                    // 验证模板的基本结构
                    if (parsedTemplate && Array.isArray(parsedTemplate.tableStructure)) {
                        currentSettings.tableTemplate = templateEntry.content; // 存储原始JSON字符串
                        showToast('success', `已从角色卡加载专用表格模板！`);
                        logDebug('%c[loadTemplateFromLorebook] 成功加载并应用了角色卡专用模板。', 'color: #2ecc71; font-weight: bold;');
                        return true;
                    } else {
                        logWarn('[loadTemplateFromLorebook] 专用模板条目内容格式无效 (缺少 tableStructure 数组)。');
                        showToast('warning', '角色卡模板格式错误，将使用全局设置。');
                        return false;
                    }
                } catch (e) {
                    logError('[loadTemplateFromLorebook] 解析专用模板条目内容时出错:', e);
                    showToast('error', '解析角色卡模板失败，将使用全局设置。');
                    return false;
                }
            } else {
                logDebug('[loadTemplateFromLorebook] 未在主世界书中找到专用模板条目，使用全局/默认模板。');
                return false;
            }
        } catch (e) {
            logError('[loadTemplateFromLorebook] 检查世界书时出错:', e);
            showToast('error', '读取世界书时出错，或未发现世界书');
            return false;
        }
    }

    async function loadTableDataFromChat() {
        logDebug('[loadTableDataFromChat] 开始执行...');
        const lastMessageId = TavernHelper_API.getLastMessageId();
        if (lastMessageId < 0) {
            logWarn('[loadTableDataFromChat] 聊天记录为空，将初始化新数据。');
            currentTableData = await initializeTableData();
            return;
        }

        const chat = await TavernHelper_API.getChatMessages(`0-${lastMessageId}`);

        for (let i = chat.length - 1; i >= 0; i--) {
            const message = chat[i];
            logDebug(`[loadTableDataFromChat] 检查消息 #${message.message_id} (role: ${message.role})`);
            if (message.role === 'assistant' && message.data && message.data[CHAT_DATA_KEY]) {
                try {
                    const payload = message.data[CHAT_DATA_KEY];
                    let data, diff;

                    // 兼容新旧数据结构
                    if (payload.state && payload.state.sheets) { // 新结构
                        data = payload.state;
                        diff = payload.diff;
                    } else if (payload.sheets) { // 旧结构
                        data = payload;
                        diff = null;
                    } else {
                        throw new Error("无效的数据负载格式");
                    }

                    currentTableData = JSON.parse(JSON.stringify(data));
                    if (diff) {
                        currentTableData.diff = JSON.parse(JSON.stringify(diff)); // 附加差异信息
                    } else {
                        delete currentTableData.diff; // 确保没有旧的差异信息
                    }

                    logDebug(`%c[loadTableDataFromChat] 成功从消息 #${message.message_id} 加载了表格数据。`, 'color: #2ecc71; font-weight: bold;');
                    return;
                } catch (e) {
                    logError(`[loadTableDataFromChat] 解析或验证消息 #${message.message_id} 的表格数据失败`, e);
                }
            }
        }
        logWarn('[loadTableDataFromChat] 遍历完所有消息后未找到有效表格数据，将初始化新数据。');
        currentTableData = await initializeTableData();
    }

    async function initializeTableData() {
        logDebug("[initializeTableData] 正在从模板初始化...");
        try {
            const template = JSON.parse(currentSettings.tableTemplate);
            const newTableDataObject = { sheets: {} };
            if (template.tableStructure && Array.isArray(template.tableStructure)) {
                template.tableStructure.forEach(tableDef => {
                    const sheetUid = generateUid('sheet_');
                    const newSheet = {
                        uid: sheetUid,
                        name: tableDef.tableName,
                        tableIndex: tableDef.tableIndex,
                        hashSheet: [],
                        cellHistory: [],
                    };
                    const headers = [null, ...tableDef.columns];
                    const headerRowUids = headers.map(headerValue => {
                        const cell = { 
                            uid: generateUid('cell_'),
                            data: { value: headerValue === null ? '' : headerValue }
                        };
                        newSheet.cellHistory.push(cell);
                        return cell.uid;
                    });
                    newSheet.hashSheet.push(headerRowUids);
                    newTableDataObject.sheets[sheetUid] = newSheet;
                });
                logDebug("[initializeTableData] 初始化成功。");
                return newTableDataObject;
            } else {
                logError("[initializeTableData] 模板格式不是预期的 tableStructure 格式。");
                showToast('error', '模板格式错误，无法初始化表格！');
                return { sheets: {} };
            }
        } catch (e) {
            logError("[initializeTableData] 从模板初始化表格失败", e);
            showToast('error', '模板JSON格式错误，无法初始化表格！');
            return { sheets: {} };
        }
    }

    async function saveTableDataToChat(messageId, dataToSave, diffInfo = null) {
        if (!dataToSave) {
            logError("[saveTableDataToChat] 保存失败：要保存的数据为空。");
            return;
        }
        if (typeof messageId !== 'number' || messageId < 0) {
            logWarn(`[saveTableDataToChat] 保存警告：无效的消息ID "${messageId}"，数据将不会被附加。`);
            return;
        }

        try {
            const existingMessage = (await TavernHelper_API.getChatMessages(messageId))[0];
            const newDataPayload = {
                state: dataToSave,
                diff: diffInfo
            };
            const newData = { ...(existingMessage.data || {}), [CHAT_DATA_KEY]: newDataPayload };

            await TavernHelper_API.setChatMessages(
                [{ message_id: messageId, data: newData }],
                { refresh: 'none' }
            );
            logDebug(`%c[saveTableDataToChat] 表格数据 (v3) 和 diff 已成功保存到消息 #${messageId}`, 'color: #2ecc71; font-weight: bold;');
        } catch (e) {
            logError(`[saveTableDataToChat] 保存数据到消息 #${messageId} 时失败:`, e);
            showToast('error', '保存表格数据失败。');
        }
    }

    function getTableDataAsPromptText() {
        if (!currentTableData || !currentTableData.sheets) return "【错误：表格数据未加载】";

        const sheets = Object.values(currentTableData.sheets)
            .filter(v => v && v.uid && v.uid.startsWith('sheet_'))
            .sort((a, b) => a.tableIndex - b.tableIndex);

        let markdownOutput = "";

        sheets.forEach(sheet => {
            if (!sheet.hashSheet || sheet.hashSheet.length === 0) return;
            const cellMap = new Map(sheet.cellHistory.map(cell => [cell.uid, cell]));

            markdownOutput += `### 【${sheet.tableIndex}:${sheet.name}】\n\n`;

            const headerUids = sheet.hashSheet[0].slice(1);
            const headers = headerUids.map(uid => cellMap.get(uid)?.data?.value || '');

            markdownOutput += `【rowIndex】|${headers.map((h, i) => `【${i}:${h}】`).join(' | ')} |\n`;
            markdownOutput += `            |${headers.map(() => '-').join('|')}|\n`;

            sheet.hashSheet.slice(1).forEach((rowUids, i) => {
                const rowContent = rowUids.slice(1).map(uid => {
                    const cell = cellMap.get(uid);
                    const value = cell?.data?.value ?? '';
                    return escapeHtml(value).replace(/\|/g, '\\|').replace(/\n/g, '<br>');
                }).join(' | ');
                markdownOutput += `【${i}】       | ${rowContent} |\n`;
            });
            markdownOutput += `\n`;
        });

        return markdownOutput.trim();
    }

    async function parseAndApplyEdits(currentMessage) {
        logDebug(`[parseAndApplyEdits] 开始处理消息 #${currentMessage.message_id} 的编辑指令。`);
        const lastMessageId = TavernHelper_API.getLastMessageId();
        if (lastMessageId < 0) {
            logError("[parseAndApplyEdits] 无法处理，聊天记录为空。");
            return;
        }

        const chat = await TavernHelper_API.getChatMessages(`0-${lastMessageId}`);
        let previousState = null;
        let diffInfo = {};

        for (let i = chat.length - 1; i >= 0; i--) {
            const prevMsg = chat[i];
            if (prevMsg.message_id < currentMessage.message_id && prevMsg.role === 'assistant' && prevMsg.data && prevMsg.data[CHAT_DATA_KEY]) {
                try {
                    const payload = prevMsg.data[CHAT_DATA_KEY];
                    const data = payload.state || payload; // 兼容新旧格式
                    if (!data.sheets) throw new Error("旧数据格式或无效数据");
                    previousState = JSON.parse(JSON.stringify(data));
                    logDebug(`[parseAndApplyEdits] 找到了基于消息 #${prevMsg.message_id} 的状态。`);
                    break;
                } catch (e) {
                    logError(`[parseAndApplyEdits] 解析消息 #${prevMsg.message_id} 的表格数据失败`, e);
                }
            }
        }

        if (!previousState) {
            logWarn("[parseAndApplyEdits] 未在历史消息中找到表格数据，将从模板初始化一个临时基准状态。");
            previousState = await initializeTableData(); 
        }

        let newState = JSON.parse(JSON.stringify(previousState));

        const aiResponse = currentMessage.message;
        const match = aiResponse.match(AI_DATA_BLOCK_REGEX);

        if (!match || !match[1]) {
            logDebug(`[parseAndApplyEdits] 消息 #${currentMessage.message_id} 中未找到 <tableEdit> 块。数据将沿用上一条消息的状态。`);
            await saveTableDataToChat(currentMessage.message_id, newState, null);
            await loadTableDataFromChat();
            renderDataPanel();
            return;
        }

        const editsString = match[1].replace(/<!--|-->/g, '').trim();
        logDebug(`[parseAndApplyEdits] 提取到的编辑指令:`, editsString);

        const functionRegex = /(updateRow|deleteRow|insertRow)\s*\(([\s\S]*?)\)/g;
        let appliedCount = 0;
        let regexMatch;

        const sheets = Object.values(newState.sheets)
            .filter(v => v && v.uid && v.uid.startsWith('sheet_'))
            .sort((a, b) => a.tableIndex - b.tableIndex);

        while ((regexMatch = functionRegex.exec(editsString)) !== null) {
            try {
                const command = regexMatch[1];
                const argsString = regexMatch[2].replace(/[\uff01-\uff5e]/g, ch => String.fromCharCode(ch.charCodeAt(0) - 0xfee0)).replace(/\s+/g, ' ').trim();
                logDebug(`[parseAndApplyEdits] 正在尝试应用指令: ${command} with args: ${argsString}`);

                const objectStartIndex = argsString.indexOf('{');
                let numericArgs = [];
                let dataString = '';

                if (command === 'deleteRow') {
                    numericArgs = argsString.split(',').map(s => s.trim()).filter(s => s);
                } else {
                    if (objectStartIndex !== -1) {
                        const numericPart = argsString.substring(0, objectStartIndex).trim();
                        numericArgs = (numericPart.endsWith(',') ? numericPart.slice(0, -1) : numericPart).split(',').map(s => s.trim()).filter(s => s);
                        dataString = argsString.substring(objectStartIndex).trim();
                    } else {
                        numericArgs = argsString.split(',').map(s => s.trim()).filter(s => s);
                    }
                }

                const tableIndex = parseInt(numericArgs[0], 10);
                if (isNaN(tableIndex)) {
                    logWarn(`[parseAndApplyEdits] 指令无效：tableIndex "${numericArgs[0]}" 不是一个数字。`);
                    continue;
                }

                const sheet = sheets.find(s => s.tableIndex === tableIndex);
                if (!sheet) {
                    logWarn(`[parseAndApplyEdits] 指令无效：找不到索引为 ${tableIndex} 的表格。`);
                    continue;
                }

                if (!diffInfo[sheet.uid]) {
                    diffInfo[sheet.uid] = { updated: [], added: [], deleted: [] };
                }

                switch(command) {
                    case 'updateRow':
                    case 'insertRow': {
                        const isUpdate = command === 'updateRow';
                        const rowIndex = isUpdate ? parseInt(numericArgs[1], 10) : -1;

                        if (isUpdate && isNaN(rowIndex)) { logWarn(`[updateRow] rowIndex "${numericArgs[1]}" 不是数字。`); break; }
                        if (!dataString.startsWith('{') || !dataString.endsWith('}')) { logWarn(`[${command}] dataString 格式错误: ${dataString}`); break; }

                        const data = {};
                        const dataContent = dataString.slice(1, -1).trim();
                        const pairRegex = /(\d+)\s*:\s*(?:'((?:\\'|[^'])*)'|"((?:\\"|[^"])*)"|([^,}\s]+))/g;
                        let pairMatch;
                        while ((pairMatch = pairRegex.exec(dataContent)) !== null) {
                            const key = pairMatch[1];
                            const singleQuotedValue = pairMatch[2];
                            const doubleQuotedValue = pairMatch[3];
                            const unquotedValue = pairMatch[4];

                            let value;
                            if (singleQuotedValue !== undefined) {
                                value = singleQuotedValue.replace(/\\'/g, "'");
                            } else if (doubleQuotedValue !== undefined) {
                                value = doubleQuotedValue.replace(/\\"/g, '"');
                            } else if (unquotedValue !== undefined) {
                                value = unquotedValue.trim();
                            } else {
                                value = '';
                            }
                            data[key] = value;
                        }

                        if (Object.keys(data).length === 0 && dataContent.length > 0) { logWarn(`[${command}] 无法从 "${dataContent}" 解析任何数据对。`); break; }

                        if (isUpdate) {
                            const rIdx = rowIndex + 1;
                            if (rIdx < 1 || rIdx >= sheet.hashSheet.length) { logWarn(`[updateRow] rowIndex ${rowIndex} 超出范围。`); break; }

                            Object.entries(data).forEach(([colIndexStr, value]) => {
                                const cIdx = parseInt(colIndexStr, 10) + 1;
                                if (sheet.hashSheet[rIdx] && sheet.hashSheet[rIdx][cIdx] !== undefined) {
                                    const newCell = { uid: generateUid('cell_'), data: { value: String(value) } };
                                    sheet.cellHistory.push(newCell);
                                    sheet.hashSheet[rIdx][cIdx] = newCell.uid;
                                    diffInfo[sheet.uid].updated.push({ rowIndex: rIdx - 1, colIndex: cIdx - 1 });
                                } else {
                                    logWarn(`[updateRow] colIndex ${colIndexStr} 在 rowIndex ${rowIndex} 中无效或不存在。`);
                                }
                            });
                            appliedCount++;
                        } else {
                            if (sheet.hashSheet[0]) {
                                const newRowUids = new Array(sheet.hashSheet[0].length).fill(null);
                                const rowHeaderCell = { uid: generateUid('cell_'), data: { value: '' } };
                                sheet.cellHistory.push(rowHeaderCell);
                                newRowUids[0] = rowHeaderCell.uid;

                                Object.entries(data).forEach(([colIndexStr, value]) => {
                                    const cIdx = parseInt(colIndexStr, 10) + 1;
                                    if (cIdx < newRowUids.length) {
                                        const cell = { uid: generateUid('cell_'), data: { value: String(value) } };
                                        sheet.cellHistory.push(cell);
                                        newRowUids[cIdx] = cell.uid;
                                    }
                                });
                                for (let i = 1; i < newRowUids.length; i++) {
                                    if (!newRowUids[i]) {
                                        const cell = { uid: generateUid('cell_'), data: { value: '' } };
                                        sheet.cellHistory.push(cell);
                                        newRowUids[i] = cell.uid;
                                    }
                                }
                                sheet.hashSheet.push(newRowUids);
                                diffInfo[sheet.uid].added.push(sheet.hashSheet.length - 2);
                                appliedCount++;
                            }
                        }
                        break;
                    }
                    case 'deleteRow': {
                        const rowIndex = parseInt(numericArgs[1], 10);
                        const rIdx = rowIndex + 1;
                        if (isNaN(rowIndex)) { logWarn(`[deleteRow] rowIndex "${numericArgs[1]}" 不是数字。`); break; }
                        if (rowIndex >= 0 && rowIndex < sheet.hashSheet.length - 1) {
                            const deletedRowUids = newState.sheets[sheet.uid].hashSheet[rIdx];
                            const prevCellMap = new Map(previousState.sheets[sheet.uid].cellHistory.map(cell => [cell.uid, cell]));
                            const deletedRowData = deletedRowUids.map(uid => prevCellMap.get(uid)?.data?.value ?? '');

                            diffInfo[sheet.uid].deleted.push({ rowIndex, deletedRowData });

                            sheet.hashSheet.splice(rIdx, 1);
                            appliedCount++;
                        } else {
                            logWarn(`[deleteRow] rowIndex ${rowIndex} 超出范围。`);
                        }
                        break;
                    }
                }
            } catch (e) {
                logError(`[parseAndApplyEdits] 解析或应用指令时捕获到异常: "${regexMatch[0]}"`, e);
            }
        }

        if (appliedCount > 0) {
        } else {
            logWarn(`[parseAndApplyEdits] 找到了<tableEdit>块，但没有成功应用任何指令。`);
        }
        await saveTableDataToChat(currentMessage.message_id, newState, diffInfo);
        await loadTableDataFromChat();
        renderDataPanel();
    }


    // --- 新增：单元格变量宏处理 ---
    /**
     * 宏回调函数，用于解析 {{表格记忆变量_t_r_c}} 格式的宏
     * @param {object} context - 宏上下文
     * @param {string} matchedString - 匹配到的完整宏字符串, e.g., "{{表格记忆变量_1_2_3}}"
     * @param {string} tableIndexStr - 捕获的表格索引字符串
     * @param {string} rowIndexStr - 捕获的行索引字符串
     * @param {string} colIndexStr - 捕获的列索引字符串
     * @returns {string} - 对应单元格的内容或错误信息
     */
    function getTableCellValue(context, matchedString, tableIndexStr, rowIndexStr, colIndexStr) {
        logDebug(`表格记忆变量宏触发: ${matchedString}`);

        if (!currentTableData || !currentTableData.sheets) {
            return `【错误：表格数据未加载】`;
        }

        try {
            const tableIndex = parseInt(tableIndexStr, 10);
            const rowIndex = parseInt(rowIndexStr, 10);
            const colIndex = parseInt(colIndexStr, 10);

            if (isNaN(tableIndex) || isNaN(rowIndex) || isNaN(colIndex)) {
                return `【错误：宏参数非数字】`;
            }

            // 找到对应的 sheet
            const sheet = Object.values(currentTableData.sheets).find(s => s.tableIndex === tableIndex);
            if (!sheet) {
                return `【错误：找不到表格号 ${tableIndex}】`;
            }

            // rowIndex是数据行的索引（0-based），所以实际在hashSheet中的索引是 rowIndex + 1 (跳过表头)
            const actualRowIndex = rowIndex + 1;
            if (actualRowIndex < 1 || actualRowIndex >= sheet.hashSheet.length) {
                return `【错误：行号 ${rowIndex} 在表格 ${tableIndex} 中越界】`;
            }
            const rowUids = sheet.hashSheet[actualRowIndex];

            // colIndex是数据列的索引（0-based），所以实际在rowUids中的索引是 colIndex + 1 (跳过行号单元格)
            const actualColIndex = colIndex + 1;
            if (actualColIndex < 1 || actualColIndex >= rowUids.length) {
                return `【错误：列号 ${colIndex} 在表格 ${tableIndex} 中越界】`;
            }

            const cellUid = rowUids[actualColIndex];
            if (!cellUid) {
                return ''; 
            }

            // 创建cellMap以便快速查找
            const cellMap = new Map(sheet.cellHistory.map(cell => [cell.uid, cell]));
            const cell = cellMap.get(cellUid);

            const value = cell?.data?.value ?? '';
            logDebug(`成功解析: 表格${tableIndex}, 行${rowIndex}, 列${colIndex} -> 值: "${value}"`);
            return String(value);

        } catch (e) {
            logError(`解析宏 ${matchedString} 时出错:`, e);
            return `【宏解析错误】`;
        }
    }


