    function addEventListeners() {
        $settingsPanel.on('click', '.tmm-close-btn', () => $settingsPanel.fadeOut(50));
        $settingsPanel.on('click', '#tmm-template-save', async () => {
            try {
                const newTemplate = $('#tmm-template-editor').val();
                JSON.parse(newTemplate);
                currentSettings.tableTemplate = newTemplate;
                saveSettings();
                showToast('success', '模板已成功保存！将为新对话应用此模板。');
                currentTableData = await initializeTableData();
                renderDataPanel();
            } catch (e) { showToast('error', '模板JSON格式错误，无法保存！'); }
        });
        $settingsPanel.on('click', '#tmm-template-reset', () => {
             if (confirm("确定要将模板恢复为默认设置吗？未保存的更改将会丢失。")) {
                currentSettings.tableTemplate = DEFAULT_TABLE_TEMPLATE;
                $('#tmm-template-editor').val(currentSettings.tableTemplate);
                showToast('info', '已恢复默认模板，点击“保存”以应用。');
             }
        });

        $dataPanel.on('click', '.tmm-close-btn', () => $dataPanel.fadeOut(50));

        $dataPanel.on('click', '.tmm-data-table-title', function() {
            const $title = $(this);
            const $tableWrapper = $title.next('.tmm-table-wrapper');
            const $icon = $title.find('.tmm-table-toggle-icon');

            $tableWrapper.slideToggle(50);
            $icon.toggleClass('expanded');
        });

        $dataPanel.on('blur', 'td[contenteditable="true"]', async function() {
            const $td = $(this);
            const sheetUid = $td.closest('.tmm-data-table').data('uid');
            const rowIndex = $td.parent().data('row-index');
            const colIndex = $td.data('col-index');
            const newText = $td.text();

            const sheet = currentTableData.sheets[sheetUid];
            if (!sheet) return;

            const rIdx = rowIndex + 1;
            const cIdx = colIndex + 1;

            if (!sheet.hashSheet[rIdx] || sheet.hashSheet[rIdx][cIdx] === undefined) return;

            const cellMap = new Map(sheet.cellHistory.map(cell => [cell.uid, cell]));
            const oldCellUid = sheet.hashSheet[rIdx][cIdx];
            const oldCell = cellMap.get(oldCellUid);

            if (oldCell && oldCell.data.value === newText) return;

            const newCell = { uid: generateUid('cell_'), data: { value: newText } };
            sheet.cellHistory.push(newCell);
            sheet.hashSheet[rIdx][cIdx] = newCell.uid;

            const lastMessageId = TavernHelper_API.getLastMessageId();
            if (lastMessageId >= 0) {
                const messages = await TavernHelper_API.getChatMessages(`0-${lastMessageId}`);
                const lastAiMessage = messages.slice().reverse().find(m => m.role === 'assistant');
                if (lastAiMessage) {
                    await saveTableDataToChat(lastAiMessage.message_id, currentTableData, null);
                    showToast('info', '单元格已修改并保存。');
                } else {
                    logWarn('无法找到AI消息来保存手动编辑的数据。');
                }
            } else {
                logWarn('聊天记录为空，无法保存手动编辑的数据。');
            }
        });

        $dataPanel.on('click', '#tmm-export-excel', handleExportToExcel);
        $dataPanel.on('click', '#tmm-import-excel', () => {
            const uploader = $('#tmm-excel-file-input');
            uploader.off('change').on('change', handleImportFromExcel);
            uploader.trigger('click');
        });
    }

    function renderDataPanel() {
        if (!$dataPanel) return;
        const container = $dataPanel.find('.tmm-table-container').empty();
        if (!currentTableData || !currentTableData.sheets) {
            container.html('<p>无表格数据可显示。请开始对话以初始化。</p>');
            return;
        }

        const diff = currentTableData.diff;

        const sheets = Object.values(currentTableData.sheets)
            .filter(v => v && v.uid && v.uid.startsWith('sheet_'))
            .sort((a, b) => a.tableIndex - b.tableIndex);

        if (sheets.length === 0) {
            container.html('<p>模板中未定义任何表格。</p>');
            return;
        }

        sheets.forEach(sheet => {
            if (!sheet.hashSheet || sheet.hashSheet.length === 0) return;
            const cellMap = new Map(sheet.cellHistory.map(cell => [cell.uid, cell]));
            const sheetDiff = diff ? diff[sheet.uid] : null;

            const titleHTML = `
                <h4 class="tmm-data-table-title">
                    <span>${escapeHtml(sheet.name)} (索引: ${sheet.tableIndex})</span>
                    <i class="fa-solid fa-chevron-down tmm-table-toggle-icon"></i>
                </h4>`;

            let tableHTML = `<div class="tmm-table-wrapper"><table class="tmm-data-table" data-uid="${sheet.uid}">`;

            const headerUids = sheet.hashSheet[0];
            tableHTML += '<thead><tr>';
            headerUids.slice(1).forEach((uid, i) => tableHTML += `<th>${escapeHtml(cellMap.get(uid)?.data?.value || '')} (${i})</th>`);
            tableHTML += '</tr></thead>';

            tableHTML += '<tbody>';

            let renderRows = [];
            sheet.hashSheet.slice(1).forEach((row, i) => {
                renderRows.push({ type: 'normal', data: row, originalIndex: i });
            });
            if (sheetDiff && sheetDiff.deleted) {
                sheetDiff.deleted.forEach(deleted => {
                    renderRows.push({ type: 'deleted', data: deleted.deletedRowData, originalIndex: deleted.rowIndex });
                });
            }
            renderRows.sort((a, b) => a.originalIndex - b.originalIndex);

            renderRows.forEach(rowInfo => {
                let rowClass = '';
                let rowHtml = '';

                if (rowInfo.type === 'deleted') {
                    rowClass = 'tmm-row-deleted';
                    rowInfo.data.slice(1).forEach(cellValue => {
                        rowHtml += `<td>${escapeHtml(cellValue)}</td>`;
                    });
                } else { // 'normal'
                    const rowIndex = rowInfo.originalIndex;
                    if (sheetDiff?.added?.includes(rowIndex)) {
                        rowClass = 'tmm-row-added';
                    }

                    rowInfo.data.slice(1).forEach((cellUid, colIndex) => {
                        const cellValue = cellMap.get(cellUid)?.data?.value ?? '';
                        let cellClass = '';
                        if (sheetDiff?.updated?.some(u => u.rowIndex === rowIndex && u.colIndex === colIndex)) {
                            cellClass = 'tmm-cell-updated';
                        }
                        rowHtml += `<td contenteditable="true" class="${cellClass}" data-col-index="${colIndex}">${escapeHtml(cellValue)}</td>`;
                    });
                }

                tableHTML += `<tr class="${rowClass}" data-row-index="${rowInfo.originalIndex}">${rowHtml}</tr>`;
            });

            tableHTML += '</tbody></table></div>';
            container.append(titleHTML + tableHTML);
        });
    }

