    function makePanelDraggable($thePanel, storageKey) {
        const $header = $thePanel.find('.tmm-header');
        const $resizer = $thePanel.find('.tmm-resizer');
        const $doc = jQuery_API(window.parent.document);
        const getCoords = e => e.type.startsWith('touch') ? e.originalEvent.touches[0] || e.originalEvent.changedTouches[0] : e;

        // --- 拖拽逻辑 ---
        const dragStart = function (e) {
            // 仅在点击头部本身或标题时拖拽，而不是按钮
            if (e.target !== $header[0] && !jQuery_API(e.target).is('h3')) return;

            e.preventDefault();
            const coords = getCoords(e);
            const offset = {
                left: coords.clientX - $thePanel.offset().left,
                top: coords.clientY - $thePanel.offset().top
            };

            const dragMove = function (e) {
                const moveCoords = getCoords(e);
                const pWin = window.parent || window;
                let newTop = moveCoords.clientY - offset.top;
                let newLeft = moveCoords.clientX - offset.left;

                // 边界检查
                newTop = Math.max(0, Math.min(newTop, pWin.innerHeight - $thePanel.outerHeight()));
                newLeft = Math.max(0, Math.min(newLeft, pWin.innerWidth - $thePanel.outerWidth()));

                $thePanel.css({ 
                    top: newTop + 'px', 
                    left: newLeft + 'px' 
                });
            };

            const dragEnd = function () {
                $doc.off(`mousemove.${SCRIPT_ID_PREFIX} touchmove.${SCRIPT_ID_PREFIX}`, dragMove);
                $doc.off(`mouseup.${SCRIPT_ID_PREFIX} touchend.${SCRIPT_ID_PREFIX}`, dragEnd);
                localStorage.setItem(storageKey, JSON.stringify({ top: $thePanel.css('top'), left: $thePanel.css('left'), width: $thePanel.width(), height: $thePanel.height() }));
            };

            $doc.on(`mousemove.${SCRIPT_ID_PREFIX} touchmove.${SCRIPT_ID_PREFIX}`, dragMove);
            $doc.on(`mouseup.${SCRIPT_ID_PREFIX} touchend.${SCRIPT_ID_PREFIX}`, dragEnd);
        };

        $header.on(`mousedown.${SCRIPT_ID_PREFIX} touchstart.${SCRIPT_ID_PREFIX}`, dragStart);

        // --- 缩放逻辑 ---
        const resizeStart = function(e) {
            e.preventDefault();
            const coords = getCoords(e);
            const startState = {
                x: coords.clientX,
                y: coords.clientY,
                width: $thePanel.width(),
                height: $thePanel.height(),
                minWidth: parseInt($thePanel.css('min-width'), 10) || 150,
                minHeight: parseInt($thePanel.css('min-height'), 10) || 100
            };

            const resizeMove = function(e) {
                const moveCoords = getCoords(e);
                const pWin = window.parent || window;
                const panelOffset = $thePanel.offset();

                let newWidth = startState.width + (moveCoords.clientX - startState.x);
                let newHeight = startState.height + (moveCoords.clientY - startState.y);

                // 最小尺寸检查
                if (newWidth < startState.minWidth) newWidth = startState.minWidth;
                if (newHeight < startState.minHeight) newHeight = startState.minHeight;

                // 最大尺寸检查 (边界)
                if (panelOffset.left + newWidth > pWin.innerWidth) {
                    newWidth = pWin.innerWidth - panelOffset.left;
                }
                if (panelOffset.top + newHeight > pWin.innerHeight) {
                    newHeight = pWin.innerHeight - panelOffset.top;
                }

                $thePanel.css({ width: newWidth + 'px', height: newHeight + 'px' });
            };

            const resizeEnd = function() {
                $doc.off(`mousemove.${SCRIPT_ID_PREFIX} touchmove.${SCRIPT_ID_PREFIX}`, resizeMove);
                $doc.off(`mouseup.${SCRIPT_ID_PREFIX} touchend.${SCRIPT_ID_PREFIX}`, resizeEnd);
                localStorage.setItem(storageKey, JSON.stringify({ top: $thePanel.css('top'), left: $thePanel.css('left'), width: $thePanel.width(), height: $thePanel.height() }));
            };

            $doc.on(`mousemove.${SCRIPT_ID_PREFIX} touchmove.${SCRIPT_ID_PREFIX}`, resizeMove);
            $doc.on(`mouseup.${SCRIPT_ID_PREFIX} touchend.${SCRIPT_ID_PREFIX}`, resizeEnd);
        };

        $resizer.on(`mousedown.${SCRIPT_ID_PREFIX} touchstart.${SCRIPT_ID_PREFIX}`, resizeStart);
    }

    function makeButtonDraggable(button) {
        let startX, startY, hasDragged = false, offset;
        const $doc = jQuery_API(window.parent.document);
        const getCoords = e => e.type.startsWith('touch') ? e.originalEvent.touches[0] || e.originalEvent.changedTouches[0] : e;

        const dragStart = e => {
            if ('mousedown' === e.type && 3 === e.which) return;
            button.removeClass('snapped').css({ opacity: 1, transform: 'scale(1)', cursor: 'grabbing' });
            const coords = getCoords(e);
            startX = coords.pageX;
            startY = coords.pageY;
            hasDragged = false;
            const pos = button.offset();
            offset = { y: startY - pos.top, x: startX - pos.left };
            e.preventDefault();
            $doc.on(`mousemove.${SCRIPT_ID_PREFIX} touchmove.${SCRIPT_ID_PREFIX}`, dragMove);
            $doc.one(`mouseup.${SCRIPT_ID_PREFIX} touchend.${SCRIPT_ID_PREFIX}`, dragEnd);
        };

        const dragMove = e => {
            const coords = getCoords(e);
            if (Math.abs(coords.pageX - startX) > 5 || Math.abs(coords.pageY - startY) > 5) hasDragged = true;
            let newTop = coords.pageY - offset.y;
            let newLeft = coords.pageX - offset.x;
            const pWin = window.parent || window;
            newTop = Math.max(0, Math.min(newTop, pWin.innerHeight - button.outerHeight()));
            newLeft = Math.max(0, Math.min(newLeft, pWin.innerWidth - button.outerWidth()));
            button.css({ top: newTop + 'px', left: newLeft + 'px', right: 'auto', bottom: 'auto' });
        };

        const dragEnd = () => {
            $doc.off(`mousemove.${SCRIPT_ID_PREFIX} touchmove.${SCRIPT_ID_PREFIX}`);
            button.css('cursor', 'grab');
            if (!hasDragged) {
                toggleDataPanel();
                return;
            }
            const pWin = window.parent || window;
            const winWidth = pWin.innerWidth;
            const btnPos = button.offset();
            const btnWidth = button.outerWidth();
            const snapThreshold = 10;
            const snappedLeft = -(btnWidth * 2 / 3);
            const snappedRight = winWidth - (btnWidth / 3);
            let newPos = { left: btnPos.left };
            let shouldSnap = false;

            if (btnPos.left < snapThreshold) {
                newPos.left = snappedLeft;
                shouldSnap = true;
            } else if (btnPos.left + btnWidth > winWidth - snapThreshold) {
                newPos.left = snappedRight;
                shouldSnap = true;
            }

            if (shouldSnap) {
                button.addClass('snapped').animate({ ...newPos, opacity: 0.6, transform: 'scale(0.9)' }, 200, 'swing', function() {
                    localStorage.setItem(STORAGE_KEY_BUTTON_POS, JSON.stringify(jQuery_API(this).offset()));
                });
            } else {
                button.removeClass('snapped');
                localStorage.setItem(STORAGE_KEY_BUTTON_POS, JSON.stringify(btnPos));
            }
        };

        button.on(`mousedown.${SCRIPT_ID_PREFIX} touchstart.${SCRIPT_ID_PREFIX}`, dragStart);
    }

    function applyInitialSnap(button) {
        const pWin = window.parent || window;
        const btnPos = button.offset();
        if (!btnPos) return;
        const snapThreshold = 10;
        if (btnPos.left < snapThreshold || btnPos.left + button.outerWidth() > pWin.innerWidth - snapThreshold) {
            button.css({ opacity: 0.6, transform: 'scale(0.9)' }).addClass('snapped');
        }
    }

