    // Refactored event handlers
    async function handleMessageContentUpdate(rawMessageId) {
        if (!currentSettings.enabled || !currentSettings.autoUpdate || isUpdating) return;

        let messageId;
        // 修复：更稳健地从事件参数中提取 messageId
        if (typeof rawMessageId === 'object' && rawMessageId !== null && typeof rawMessageId.message_id === 'number') {
            messageId = rawMessageId.message_id;
        } else if (!isNaN(parseInt(rawMessageId, 10))) {
            messageId = parseInt(rawMessageId, 10);
        } else {
            logWarn(`[handleMessageContentUpdate] Invalid messageId received, cannot parse:`, rawMessageId);
            return;
        }

        const messages = await TavernHelper_API.getChatMessages(messageId);
        if (!messages || messages.length === 0) {
            logWarn(`[handleMessageContentUpdate] Could not find message with ID ${messageId}`);
            return;
        }
        const message = messages[0];

        if (message && message.role === 'assistant') {
            isUpdating = true;
            try {
                await parseAndApplyEdits(message);
            } finally {
                isUpdating = false;
            }
        }
    }

    async function handleChatStateChange() {
        if (isUpdating) return;
        isUpdating = true;
        try {
            logDebug(`[handleChatStateChange] Chat state changed (e.g., delete/swipe). Reloading table data.`);
            await loadTableDataFromChat();
            renderDataPanel();
        } finally {
            isUpdating = false;
        }
    }

    // --- Excel 导入/导出 ---
    async function handleExportToExcel() {
        const parentWin = typeof window.parent !== 'undefined' ? window.parent : window;
        if (!parentWin.XLSX) {
            showToast('error', 'Excel处理库未加载，请稍等或刷新页面。');
            return;
        }
        if (!currentTableData || !currentTableData.sheets) {
            showToast('warning', '没有可导出的表格数据。');
            return;
        }

        try {
            const wb = parentWin.XLSX.utils.book_new();
            const sortedSheets = Object.values(currentTableData.sheets)
                .filter(Boolean)
                .sort((a, b) => a.tableIndex - b.tableIndex);

            sortedSheets.forEach(sheet => {
                const cellMap = new Map(sheet.cellHistory.map(cell => [cell.uid, cell]));
                const dataForSheet = sheet.hashSheet.map(rowUids => 
                    rowUids.slice(1).map(uid => cellMap.get(uid)?.data?.value ?? '')
                );
                const ws = parentWin.XLSX.utils.aoa_to_sheet(dataForSheet);
                parentWin.XLSX.utils.book_append_sheet(wb, ws, sheet.name);
            });

            const characterName = SillyTavern_API.getContext().name2 || 'character';
            parentWin.XLSX.writeFile(wb, `${characterName}_表格数据.xlsx`);
            showToast('success', 'Excel文件已开始导出。');
        } catch(e) {
            logError('导出Excel失败:', e);
            showToast('error', '导出Excel文件时出错。');
        }
    }

    async function handleImportFromExcel(event) {
        const parentWin = typeof window.parent !== 'undefined' ? window.parent : window;
        if (!parentWin.XLSX) {
            showToast('error', 'Excel处理库未加载，请稍等或刷新页面。');
            return;
        }
        const file = event.target.files[0];
        if (!file) return;

        if (!confirm("这将用Excel文件中的数据覆盖当前所有表格。此操作无法撤销。是否继续？")) {
            event.target.value = ''; // 重置文件输入
            return;
        }

        const reader = new FileReader();
        reader.onload = async (e) => {
            try {
                const data = new Uint8Array(e.target.result);
                const workbook = parentWin.XLSX.read(data, { type: 'array' });
                const newTableData = { sheets: {} };

                workbook.SheetNames.forEach((sheetName, index) => {
                    const ws = workbook.Sheets[sheetName];
                    const aoa = parentWin.XLSX.utils.sheet_to_json(ws, { header: 1, defval: '' });
                    if (aoa.length === 0) return;

                    const sheetUid = generateUid('sheet_');
                    const newSheet = { uid: sheetUid, name: sheetName, tableIndex: index, hashSheet: [], cellHistory: [] };

                    // 处理表头
                    const headers = [null, ...aoa[0]];
                    const headerRowUids = headers.map(headerValue => {
                        const cell = { uid: generateUid('cell_'), data: { value: headerValue === null ? '' : String(headerValue) }};
                        newSheet.cellHistory.push(cell);
                        return cell.uid;
                    });
                    newSheet.hashSheet.push(headerRowUids);

                    // 处理数据行
                    aoa.slice(1).forEach(rowData => {
                        const rowWithIndexPlaceholder = ['', ...rowData];
                        const dataRowUids = rowWithIndexPlaceholder.map(cellValue => {
                            const cell = { uid: generateUid('cell_'), data: { value: String(cellValue) }};
                            newSheet.cellHistory.push(cell);
                            return cell.uid;
                        });
                        newSheet.hashSheet.push(dataRowUids);
                    });
                    newTableData.sheets[sheetUid] = newSheet;
                });

                currentTableData = newTableData;
                const lastMessageId = TavernHelper_API.getLastMessageId();
                if (lastMessageId >= 0) {
                    const messages = await TavernHelper_API.getChatMessages(`0-${lastMessageId}`);
                    const lastAiMessage = messages.slice().reverse().find(m => m.role === 'assistant');
                    if (lastAiMessage) {
                        await saveTableDataToChat(lastAiMessage.message_id, currentTableData, null);
                        showToast('success', '数据导入成功并已保存！');
                    } else {
                        showToast('warning', '数据已导入，但找不到AI消息来附加数据。将在下次AI回复时保存。');
                    }
                } else {
                     showToast('warning', '数据已导入，但聊天记录为空。将在下次AI回复时保存。');
                }

                renderDataPanel();

            } catch (err) {
                logError('导入Excel失败:', err);
                showToast('error', '导入或解析Excel文件时出错。');
            } finally {
                event.target.value = ''; // 导入后重置文件输入
            }
        };
        reader.readAsArrayBuffer(file);
    }

    function loadScript(url, callback) {
        const parentWin = typeof window.parent !== 'undefined' ? window.parent : window;
        if (parentWin.XLSX) {
            if (callback) callback();
            return;
        }
        const script = parentWin.document.createElement('script');
        script.type = 'text/javascript';
        script.src = url;
        if (callback) {
            script.onload = callback;
        }
        script.onerror = () => {
            logError(`Failed to load script: ${url}`);
            showToast('error', `加载核心库失败: ${url}`);
        };
        parentWin.document.head.appendChild(script);
    }

    async function mainInitialize() {
        logDebug('脚本初始化...');
        const parentWin = typeof window.parent !== 'undefined' ? window.parent : window;
        SillyTavern_API = parentWin.SillyTavern;
        TavernHelper_API = parentWin.TavernHelper;
        jQuery_API = parentWin.jQuery || parentWin.$;
        toastr_API = parentWin.toastr;

        if (SillyTavern_API && TavernHelper_API && jQuery_API) {
            isApiReady = true;
            logDebug('核心API已就绪。');

            loadScript('https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js', () => {
                logDebug('SheetJS (xlsx) library loaded successfully.');
            });

            cleanup();
            loadSettings();
            await loadTemplateFromLorebook(); // 新增：在初始化时为已打开的聊天加载模板
            createUI();
            addMenuItem();
            initializeViewerButton();

            TavernHelper_API.registerMacroLike(/\{\{666表格记忆666\}\}/g, getTableDataAsPromptText);
            TavernHelper_API.registerMacroLike(/\{\{表格记忆变量_(\d+)_(\d+)_(\d+)\}\}/g, getTableCellValue);

            // 新增: 将核心函数暴露到父窗口对象，供其他脚本调用
            if (!parentWin.TableMemoryMasterAPI) {
                parentWin.TableMemoryMasterAPI = {};
            }
            parentWin.TableMemoryMasterAPI.getTableAsMarkdown = getTableDataAsPromptText;
            parentWin.TableMemoryMasterAPI.getCellValueByMacro = getTableCellValue;
            logDebug('表格记忆大师 API 已暴露到 parentWin.TableMemoryMasterAPI');

            eventOn(tavern_events.CHAT_CHANGED, async () => {
                logDebug(`[CHAT_CHANGED] 事件触发。`);
                loadSettings(); // 重新加载全局设置以防万一
                await loadTemplateFromLorebook(); // 每次切换角色时都检查专用模板
                await loadTableDataFromChat();

                const lastMessageId = TavernHelper_API.getLastMessageId();
                logDebug(`[CHAT_CHANGED] 最新消息ID: ${lastMessageId}`);

                if (lastMessageId >= 0) {
                    const messages = await TavernHelper_API.getChatMessages(lastMessageId);
                    if (!messages || messages.length === 0) {
                        logWarn(`[CHAT_CHANGED] 无法获取最新消息 (ID: ${lastMessageId})`);
                        renderDataPanel();
                        return;
                    }
                    const lastMessage = messages[0];
                    logDebug(`[CHAT_CHANGED] 最后一条消息 (ID: ${lastMessage.message_id}):`, JSON.stringify(lastMessage, null, 2));

                    const hasTableEdit = lastMessage.message && lastMessage.message.match(AI_DATA_BLOCK_REGEX);
                    const noChatData = !lastMessage.data || !lastMessage.data[CHAT_DATA_KEY];

                    logDebug(`[CHAT_CHANGED] 条件检查: role=${lastMessage.role}, has_message=${!!lastMessage.message}, has_tableEdit=${!!hasTableEdit}, no_chat_data=${noChatData}`);

                    if (lastMessage && lastMessage.role === 'assistant' && hasTableEdit && noChatData) {
                        logDebug(`%c[CHAT_CHANGED] 检测到最后一条AI消息 #${lastMessage.message_id} 中有未处理的 tableEdit 块，正在调用 parseAndApplyEdits...`, 'color: #f39c12; font-weight: bold;');
                        await parseAndApplyEdits(lastMessage);
                    } else {
                        logDebug('[CHAT_CHANGED] 无需处理最后一条消息，直接渲染数据面板。');
                        renderDataPanel();
                    }
                } else {
                    logDebug('[CHAT_CHANGED] 聊天记录为空，渲染数据面板。');
                    renderDataPanel();
                }
            });

            // Re-bind events with new handlers
            eventOn(tavern_events.MESSAGE_RECEIVED, handleMessageContentUpdate);
            eventOn(tavern_events.MESSAGE_EDITED, handleMessageContentUpdate);
            eventOn(tavern_events.MESSAGE_UPDATED, handleMessageContentUpdate);
            eventOn(tavern_events.MESSAGE_SWIPED, handleMessageContentUpdate);

            eventOn(tavern_events.MESSAGE_DELETED, handleChatStateChange);

            await loadTableDataFromChat(); // 为初次加载执行数据加载
        } else {
            logError('一个或多个核心API未找到。脚本无法运行。');
        }
    }

    let checkInterval = setInterval(() => {
        const parentWin = typeof window.parent !== 'undefined' ? window.parent : window;
        if (parentWin.jQuery && parentWin.SillyTavern && parentWin.TavernHelper) {
            clearInterval(checkInterval);
            (parentWin.jQuery || parentWin.$)(parentWin.document).ready(mainInitialize);
        }
    }, 500);

})();

