            "N003",
            "N010",
            "N011",
            "N012",
            "N013"
          ],
          "后置节点": [
            "N005",
            "N006",
            "N007",
            "N008",
            "N009"
          ],
          "通向结局": null
        },
        {
          "节点ID": "N005",
          "时间": "探索/行动1",
