        },
        {
          "节点ID": "N020",
          "时间": "探索/行动1",
          "节点描述": "萧焱在药老的指引下，前往人迹罕至的天羽宫后山。此行动的核心是“寻宝与风险”。他需要根据药老描述的特征，寻找特定年份和品相的低阶灵草。过程中可能会遭遇守护药草的低阶魔兽，需要运用新学到的技巧进行战斗；也可能撞见同样来历练的宗门弟子，需要巧妙地隐藏实力与目的，避免暴露。",
          "前置节点": [
            "N019"
          ],
          "后置节点": [
