          "前置节点": [
            "N020"
          ],
          "后置节点": [
            "N019"
          ],
          "通向结局": null
        },
        {
          "节点ID": "N025",
          "时间": "探索/行动2完成",
          "节点描述": "完成一次痛苦而有效的淬体，感受到实力精进。",
          "前置节点": [
            "N021"
          ],
          "后置节点": [
            "N019"
          ],
          "通向结局": null
        },
        {
          "节点ID": "N026",
